import numpy as np
def load(f):
    L=open(f).read().split("\n"); n=int(L[0])
    ats=[l.split() for l in L[2:2+n]]
    return [a[0] for a in ats], np.array([[float(x) for x in a[1:4]] for a in ats])
s,xyz=load("opt1.xyz")
def d(i,j): return round(float(np.linalg.norm(xyz[i]-xyz[j])),2)
